        // To cause a revert path for non-owner, we first change owner to a different address (if desired)
        // by calling setOwner as the owner. To keep the call shape flat, perform that setup explicitly.

        // If we want to test a non-owner calling setOwner, we first transfer ownership away so that
        // the subsequent setOwner (performed by this contract) will revert because msg.sender != owner.

        // Decide which scenario to take based on callAsOwner:
        // - If callAsOwner == true: perform only one call which attempts to set owner to candidate (should succeed).
        // - If callAsOwner == false: first transfer ownership to an arbitrary other address (candidate != beforeOwner recommended by caller),
        //   then attempt to setOwner to candidate again which should revert, leaving owner unchanged.

        bool firstCallSucceeded;
        bool secondCallReverted;

        if (callAsOwner) {
            // Single top-level state-changing call: this contract (the owner) calls setOwner
            try c.setOwner(candidate) returns (bool ok) {
                firstCallSucceeded = ok;
                secondCallReverted = false;
            } catch {
                firstCallSucceeded = false;
                secondCallReverted = true;
            }

            address afterOwner = c.owner();

            // If the call did not revert it must have returned true and owner must equal candidate.
            // If it reverted, owner must remain unchanged.
            assert((!secondCallReverted && firstCallSucceeded && afterOwner == candidate) || (secondCallReverted && afterOwner == beforeOwner));
        } else {
            // We will perform two top-level calls on c as required by the rule shape:
            // 1) transfer ownership away from this contract to an arbitrary address 'candidate' (this call should succeed)
            // 2) attempt to setOwner back to candidate (this call is made by this contract but should now revert because it's no longer owner)

            // First call: this contract (current owner) sets owner to candidate (should succeed)
            try c.setOwner(candidate) returns (bool ok1) {
                firstCallSucceeded = ok1;
