                secondReverted = true;
            }

            address afterOwner2 = c.owner();

            // General rule for this scenario:
            // - The first call (by the owner) if it succeeded must have returned true and updated owner to candidate.
            // - The second call (by non-owner) must revert and owner must remain as set by the first call.
            assert((firstCallSucceeded && midOwner == candidate && secondReverted && afterOwner2 == midOwner) || (!firstCallSucceeded && afterOwner2 == beforeOwner));
        }
    }

